"""Supplement table parsing and row filtering. Fixtures are generated by
col4a1a2-dev fixtures, so no publisher bytes are redistributed."""

from pathlib import Path
from typing import ClassVar

import pytest

from col4a1a2.sources import tabular

FIX = Path(__file__).parent / "fixtures"


@pytest.mark.parametrize("ext", ["xlsx", "csv", "docx", "pdf"])
def test_every_parser_recovers_the_variants(ext):
    data = (FIX / f"supplement_variants.{ext}").read_bytes()
    sheets = tabular.parse(data, ext)
    assert sheets, f"{ext} produced no sheets"
    text, _ = tabular.sheets_to_text("Supplementary Table 1", f"f.{ext}", [tabular.filter_rows(s) for s in sheets])
    for token in ("COL4A1", "c.1537G>A", "p.Gly513Ser", "COL4A2", "c.4493C>T"):
        assert token in text, f"{ext} lost {token}"


def test_rendered_text_matches_the_body_table_format():
    sheets = [tabular.filter_rows(s) for s in tabular.parse((FIX / "supplement_variants.csv").read_bytes(), "csv")]
    text, _ = tabular.sheets_to_text("eTable 2", "f.csv", sheets)
    assert text.startswith("=== SUPPLEMENTARY FILE: eTable 2 (parsed from f.csv) ===")
    assert "[TABLE]" in text
    assert " | " in text


def test_large_sheet_is_filtered_but_keeps_the_relevant_row():
    sheets = tabular.parse((FIX / "supplement_variants.xlsx").read_bytes(), "xlsx")
    big = next(s for s in sheets if s.name == "AllGenes")
    assert big.rows_total > 200
    kept = tabular.filter_rows(big)
    assert len(kept.rows) < 10, "irrelevant genes should be dropped"
    flat = " ".join(c for r in kept.rows for c in r)
    assert "c.2317G>A" in flat and "p.Gly773Arg" in flat


def test_filtering_is_never_silent():
    """A quietly truncated cohort table would make the model undercount, so the
    rendered text has to say what was dropped."""
    sheets = [tabular.filter_rows(s) for s in tabular.parse((FIX / "supplement_variants.xlsx").read_bytes(), "xlsx")]
    text, _ = tabular.sheets_to_text("eTable", "f.xlsx", sheets)
    assert "kept" in text and "rows]" in text


def test_small_sheets_pass_through_whole():
    s = tabular.Sheet(name="s", rows=[["Gene"], ["NOTHINGRELEVANT"], ["ALSONOTHING"]], rows_total=3)
    assert len(tabular.filter_rows(s).rows) == 3


def test_header_rows_survive_filtering():
    rows = [["Supplementary Table 2"], ["Patient", "Gene", "Coding"], ["", "", "(GRCh38)"]]
    rows += [[f"P{i}", "OTHERGENE", "c.1A>T"] for i in range(80)]
    rows.append(["P99", "COL4A1", "c.1537G>A"])
    kept = tabular.filter_rows(tabular.Sheet(name="s", rows=rows, rows_total=len(rows)))
    assert kept.rows[:3] == rows[:3], "multi-row headers must survive"
    assert ["P99", "COL4A1", "c.1537G>A"] in kept.rows


def test_character_cap_emits_a_marker():
    rows = [["Gene", "Coding"]] + [["COL4A1", f"c.{i}G>A"] for i in range(50)]
    sheets = [tabular.Sheet(name=f"s{i}", rows=rows, rows_total=len(rows)) for i in range(5)]
    text, rendered = tabular.sheets_to_text("eTable", "f.xlsx", sheets, max_chars=400)
    assert rendered < len(sheets), "the caller must learn how many sheets were dropped"
    assert "[TRUNCATED: character cap reached" in text


def test_unsupported_and_textless_inputs_are_reported_not_guessed():
    with pytest.raises(tabular.UnsupportedSupplement, match="legacy"):
        tabular.parse(b"\xd0\xcf\x11\xe0", "xls")
    with pytest.raises(tabular.UnsupportedSupplement, match="unsupported extension"):
        tabular.parse(b"data", "avi")
    with pytest.raises(tabular.UnsupportedSupplement):
        tabular.parse(b"not a real xlsx", "xlsx")


def test_scanned_pdf_is_flagged_for_ocr_rather_than_returning_nothing():
    """A PDF with no extractable text must say so, not silently yield an empty table."""
    blank = (
        b"%PDF-1.4\n1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n"
        b"2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n"
        b"3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] >>\nendobj\n"
        b"trailer\n<< /Size 4 /Root 1 0 R >>\n%%EOF\n"
    )
    with pytest.raises(tabular.UnsupportedSupplement):
        tabular.parse(blank, "pdf")


def test_is_relevant_catches_shorthand_variant_notation():
    assert tabular.is_relevant(["P1", "COL4A1", ""])
    assert tabular.is_relevant(["P2", "", "c.1537G>A"])
    assert tabular.is_relevant(["P3", "", "G1417R"])
    assert tabular.is_relevant(["P4", "", "exon 26"])
    assert not tabular.is_relevant(["P5", "SOMEGENE", "normal"])


def test_pdf_text_fallback_is_per_page_not_global(monkeypatch):
    """A table on page 1 must not stop later pages' text from being read."""

    class FakePage:
        def __init__(self, tables, text):
            self._tables, self._text = tables, text

        def extract_tables(self):
            return self._tables

        def extract_text(self):
            return self._text

    class FakePdf:
        pages: ClassVar[list] = [
            FakePage([[["Gene", "Coding"], ["COL4A1", "c.1A>T"]]], "ignored"),
            FakePage([], "Supplementary Table 2. Additional variants identified in the extended cohort.\n"
                         "Patient Gene Coding Protein Inheritance\n"
                         "P5 COL4A2 c.2G>C p.Gly1Ala de novo\n"
                         "P6 COL4A1 c.3G>T p.Gly1Val inherited\n"
                         "P7 COL4A1 c.4G>A p.Gly2Arg unknown\n"
                         "Variants are numbered against the reference transcripts given in the Methods."),
        ]

        def __enter__(self):
            return self

        def __exit__(self, *a):
            return False

    import pdfplumber

    monkeypatch.setattr(pdfplumber, "open", lambda _f: FakePdf())
    sheets = tabular.parse(b"%PDF-1.4 fake", "pdf")
    names = [s.name for s in sheets]
    assert "page 1 table 1" in names
    assert "page 2 text" in names, "page 2 text was lost"
    assert "page 1 text" not in names, "page 1 had a table, so its text is redundant"


def test_small_sheet_bypass_is_disabled_for_multi_sheet_workbooks():
    """One short variant table should pass whole; eleven sheets of gene lists
    should not."""
    noise = tabular.Sheet(name="genes", rows=[["Gene"]] + [["OTHERGENE"]] * 20, rows_total=21)
    one = tabular.filter_sheets([noise])
    assert len(one[0].rows) == 21, "a lone small sheet keeps its bypass"
    many = tabular.filter_sheets([noise] * 30)
    assert all(len(s.rows) <= 3 for s in many), "a large workbook must be filtered throughout"


def test_bypass_gate_counts_rows_not_sheets():
    """A multi-page PDF yields one sheet per page; counting sheets would gut each."""
    page = tabular.Sheet(name="page text", rows=[["Supplementary Table 2."], ["Patient Gene"],
                                                 ["P1 COL4A1"], ["Numbering follows the Methods."]],
                         rows_total=4)
    kept = tabular.filter_sheets([page] * 8)
    assert all(len(s.rows) == 4 for s in kept), "32 rows across 8 pages is small; keep them"
    assert any("Methods" in c for s in kept for r in s.rows for c in r)
